  Let POST := enq_new_post sp gp tp s7 s8 s9 s10 s11 F fc m lo U size TH qcache k hdq LA qbytes B cnt chunks j0 j1 j3.

  Hypothesis LO : ltac2:(zQ "20!luc!lv5@2$1@1$0?5HCEIL?2lo").  Hypothesis HI : ltac2:(zQ "40!rc!p5!lv5!jk7@2$2@2$1?2lo+rm0@2$3@1$0#k0?2sp").
